/* 树的孩子兄弟表示法（First-Child / Next-Sibling）*/
typedef struct Node {
    int data;                  // 节点数据域
    struct Node *firstChild;   // 指向第一个孩子节点
    struct Node *nextSibling;  // 指向下一个兄弟节点
} Node;

/* 具象锚点：用该结构体表示根为 A，A 有孩子 B、C，B 有孩子 D 的树 */
Node a = {'A', NULL, NULL};
Node b = {'B', NULL, NULL};
Node c = {'C', NULL, NULL};
Node d = {'D', NULL, NULL};
a.firstChild = &b;   // A 的第一个孩子是 B
b.nextSibling = &c;  // B 的下一个兄弟是 C
b.firstChild = &d;   // B 的第一个孩子是 D

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def bst_search(root, target):
    """在二叉搜索树中递归查找 target，返回节点或 None。

    路径示例：在根为 50 的树中搜索 37
      50 → 37 < 50，向左走
      30 → 37 > 30，向右走
      40 → 37 < 40，向左走
      35 → 37 > 35，向右走 → 命中 37 或返回 None
    """
    if root is None:
        return None

    if target < root.val:
        # 目标值更小，淘汰右子树，递归左子树
        return bst_search(root.left, target)
    elif target > root.val:
        # 目标值更大，淘汰左子树，递归右子树
        return bst_search(root.right, target)
    else:
        # 全序关系判定相等，查找命中
        return root

// 正确基例：空树是递归终止的第一道检查
int height(TreeNode* root) {
    if (root == NULL) return 0;          // 空树高度为 0
    int left  = height(root->left);      // 安全：即使单支子树为空也不会崩溃
    int right = height(root->right);
    return 1 + (left > right ? left : right);
}

// 错误示范：仅在叶子返回，遗漏空树检查
int height_wrong(TreeNode* root) {
    if (root->left == NULL && root->right == NULL)
        return 1;                        // 假设这是“叶子”
    int left  = height_wrong(root->left);   // 若左子树为空，root->left 为 NULL
    int right = height_wrong(root->right);  // 下一层解引用 NULL->left，崩溃
    return 1 + (left > right ? left : right);
}
